/// Layout of shards within one LLC pod
#[repr(C)]
#[derive(Clone, Copy)]
struct llc_shard_layout {
    /// number of large shards (cores_per_shard + 1)
    nr_large_shards: i32,
    /// base number of cores per default shard
    cores_per_shard: i32,
    /// total number of shards
    nr_shards: i32,
    // nr_default shards = (nr_shards - nr_large_shards)
}


// We don't want to trap softirq for too long. See MAX_SOFTIRQ_TIME and
// MAX_SOFTIRQ_RESTART in kernel/softirq.c. These are macros because
// msecs_to_jiffies() can't be an initializer.
// Structure fields follow one of the following exclusion rules.
//
// I: Modifiable by initialization/destruction paths and read-only for
//    everyone else.
//
// P: Preemption protected.  Disabling preemption is enough and should
//    only be modified and accessed from the local cpu.
//
// L: pool->lock protected.  Access with pool->lock held.
//
// LN: pool->lock and wq_node_nr_active->lock protected for writes. Either for
//     reads.
//
// K: Only modified by worker while holding pool->lock. Can be safely read by
//    self, while holding pool->lock or from IRQ context if %current is the
//    kworker.
//
// S: Only modified by worker self.
//
// A: wq_pool_attach_mutex protected.
//
// PL: wq_pool_mutex protected.
//
// PR: wq_pool_mutex protected for writes.  RCU protected for reads.
//
// PW: wq_pool_mutex and wq->mutex protected for writes.  Either for reads.
//
// PWR: wq_pool_mutex and wq->mutex protected for writes.  Either or
//      RCU for reads.
//
// WQ: wq->mutex protected.
//
// WR: wq->mutex protected for writes.  RCU protected for reads.
//
// WO: wq->mutex protected for writes. Updated with WRITE_ONCE() and can be read
//     with READ_ONCE() without locking.
//
// MD: wq_mayday_lock protected.
//
// WD: Used internally by the watchdog.
// struct worker is defined in workqueue_internal.h
#[repr(C)]
#[derive(Clone, Copy)]
struct worker_pool {
    /// the pool lock
    lock: raw_spinlock,
    /// I: the associated cpu
    cpu: i32,
    /// I: the associated node ID
    node: i32,
    /// I: pool ID
    id: i32,
    /// L: flags
    flags: u32,
    /// L: last forward progress timestamp
    last_progress_ts: u64,
    /// WD: stalled cpu bound pool
    cpu_stall: bool,
    /// The counter is incremented in a process context on the associated CPU
    /// w/ preemption disabled, and decremented or reset in the same context
    /// but w/ pool->lock held. The readers grab pool->lock and are
    /// guaranteed to see if the counter reached zero.
    nr_running: i32,
    /// L: list of pending works
    worklist: list_head,
    /// L: total number of workers
    nr_workers: i32,
    /// L: currently idle workers
    nr_idle: i32,
    /// L: list of idle workers
    idle_list: list_head,
    /// L: worker idle timeout
    idle_timer: timer_list,
    /// L: worker idle cleanup
    idle_cull_work: work_struct,
    /// L: SOS timer for workers
    mayday_timer: timer_list,
    /// a workers is either on busy_hash or idle_list, or the manager
    busy_hash: [hlist_head; 64],
    /// L: purely informational
    manager: *mut worker,
    /// L: last worker woken by kick_pool()
    last_woken_worker: *mut worker,
    /// A: attached workers
    workers: list_head,
    /// worker IDs for task name
    worker_ida: ida,
    /// I: worker attributes
    attrs: *mut workqueue_attrs,
    /// PL: unbound_pool_hash node
    hash_node: hlist_node,
    /// PL: refcnt for unbound pools
    refcnt: i32,
    /// Destruction of pool is RCU protected to allow dereferences
    /// from get_work_pool().
    rcu: callback_head,
    // L: hash of busy workers
}


// Per-pool_workqueue statistics. These can be monitored using
// tools/workqueue/wq_monitor.py.
/// The per-pool workqueue.  While queued, bits below WORK_PWQ_SHIFT
/// of work_struct->data are used for flags and the remaining high bits
/// point to the pwq; thus, pwqs need to be aligned at two's power of the
/// number of flag bits.
#[repr(C, align(256))]
#[derive(Clone, Copy)]
struct pool_workqueue {
    /// I: the associated pool
    pool: *mut worker_pool,
    /// I: the owning workqueue
    wq: *mut workqueue_struct,
    /// L: current color
    work_color: i32,
    /// L: flushing color
    flush_color: i32,
    /// L: reference count
    refcnt: i32,
    nr_in_flight: [i32; 16],
    /// L: nr of in_flight works
    /// L: execution suspended
    plugged: bool,
    /// nr_active management and WORK_STRUCT_INACTIVE:
    ///
    /// When pwq->nr_active >= max_active, new work item is queued to
    /// pwq->inactive_works instead of pool->worklist and marked with
    /// WORK_STRUCT_INACTIVE.
    ///
    /// All work items marked with WORK_STRUCT_INACTIVE do not participate in
    /// nr_active and all work items in pwq->inactive_works are marked with
    /// WORK_STRUCT_INACTIVE. But not all WORK_STRUCT_INACTIVE work items are
    /// in pwq->inactive_works. Some of them are ready to run in
    /// pool->worklist or worker->scheduled. Those work itmes are only struct
    /// wq_barrier which is used for flush_work() and should not participate
    /// in nr_active. For non-barrier work item, it is marked with
    /// WORK_STRUCT_INACTIVE iff it is in pwq->inactive_works.
    /// L: nr of active works
    nr_active: i32,
    /// L: inactive works
    inactive_works: list_head,
    /// LN: node on wq_node_nr_active->pending_pwqs
    pending_node: list_head,
    /// WR: node on wq->pwqs
    pwqs_node: list_head,
    /// MD: node on wq->maydays
    mayday_node: list_head,
    /// L: cursor on pool->worklist
    mayday_cursor: work_struct,
    stats: [u64; 8],
    /// Release of unbound pwq is punted to a kthread_worker. See put_pwq()
    /// and pwq_release_workfn() for details. pool_workqueue itself is also
    /// RCU protected so that the first pwq can be determined without
    /// grabbing wq->mutex.
    release_work: kthread_work,
    rcu: callback_head,
}


